    /**
     * Pwyc Max
     */
    pwyc_max?: number | string | null;
    /**
     * Vat Rate
     *
     * VAT rate override. Null = use org default.
     */
    vat_rate?: number | string | null;
    /**
     * Vat Exemption Reason
     */
    vat_exemption_reason?: string;
    /**
     * Currency
     */
    currency?: 'EUR' | 'USD' | 'GBP' | 'JPY' | 'AUD' | 'CAD' | 'CHF' | 'CNY' | 'HKD' | 'NZD' | 'SEK' | 'KRW' | 'SGD' | 'NOK' | 'MXN' | 'INR' | 'ZAR' | 'TRY' | 'BRL' | 'DKK' | 'PLN' | 'THB' | 'IDR' | 'HUF' | 'CZK' | 'ILS' | 'MYR' | 'PHP' | 'RON' | 'ISK';
    /**
     * Sales Start At
     */
    sales_start_at?: string | null;
    /**
     * Sales End At
     */
    sales_end_at?: string | null;
    /**
     * Sales Paused
     */
    sales_paused?: boolean;
    /**
     * Check In Opens Offset
     *
     * Check-in opens at event start + this (may be negative). Null = event window.
     */
    check_in_opens_offset?: string | null;
    /**
     * Check In Closes Offset
     *
     * Check-in closes at event start + this. Null = event window.
     */
    check_in_closes_offset?: string | null;
    /**
     * Total Quantity
     */
    total_quantity?: number | null;
    /**
     * Restricted To Membership Tiers Ids
     */
    restricted_to_membership_tiers_ids?: Array<string> | null;
